{
  "query": "public application shown on the home page",
  "results": [
    {
      "title": "About Bulletproof React",
      "path": "/",
      "content": "Bulletproof React showcases best practices for building React applications. This demo is a team discussions app: create an account for your team, then read and take part in team-scoped discussion threads with comments. Use \"Get started\" on the landing page to sign in. Source code: https://github.com/alan2207/bulletproof-react."
    },
    {
      "title": "Roles and permissions",
      "path": "/app",
      "content": "Two roles exist. USER (regular member): create comments in discussions and delete their own comments. ADMIN: create, edit and delete discussions, comment, delete any comment, and view the team's users list. Your role is shown on the dashboard after signing in."
    },
    {
      "title": "Discussions and comments",
      "path": "/app/discussions",
      "content": "Discussions are threads visible only to your team, listed at /app/discussions with title, author and creation date (10 per page). Open a discussion to read its body (markdown) and comments, and to add your own comment. Discussions themselves are created and edited by team admins."
    }
  ]
}

